package net.civeira.phylax.features.notification.message.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TargetVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property target of message ")
  void test_target_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> TargetVO.tryFrom(null));
    Assertions.assertEquals("one", TargetVO.from("one").getTarget());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TargetVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TargetVO.from("one").toString());
  }
}
